import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        long[] x = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long min = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            x[i] = nextLong() - a[i];
            min = Math.min(min, x[i]);
        }
        if (min < 0) {
            System.out.println(-1);
            return;
        }
        if (n == 1) {
            System.out.println(x[0]);
            return;
        }
        // Every drop between neighbours needs that many prefix operations.
        long need = 0;
        for (int i = 1; i < n; i++) need += Math.max(0, x[i - 1] - x[i]);
        System.out.println(need > x[0] ? -1 : x[n - 1] + need);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	x := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	minDiff := int64(1) << 62
	for i := range x {
		x[i] = nextInt() - a[i]
		minDiff = min(minDiff, x[i])
	}
	if minDiff < 0 {
		fmt.Println(-1)
		return
	}
	if n == 1 {
		fmt.Println(x[0])
		return
	}
	// Every drop between neighbours needs that many prefix operations.
	var need int64
	for i := 1; i < n; i++ {
		need += max(0, x[i-1]-x[i])
	}
	if need > x[0] {
		fmt.Println(-1)
	} else {
		fmt.Println(x[n-1] + need)
	}
}
